Siap! Saya buat game 2D Platformer edukasi rantai makanan dengan gaya Vibrant Cartoon Arcade dan Double Jump dalam satu berkas HTML5.

```html
<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no">
<title>Rantai Makanan: Panen Produsen</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
  html, body { width: 100%; height: 100%; overflow: hidden; background: #1a0f2e; font-family: 'Trebuchet MS', sans-serif; }
  #wrap { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; }
  #stage { position: relative; width: 100%; height: 100%; max-width: 100vw; max-height: 100vh; }
  canvas { display: block; width: 100%; height: 100%; }
  .overlay { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 20px; }
  .hidden { display: none !important; }
  h1 { font-size: clamp(22px, 4.5vw, 44px); color: #fff; text-shadow: 3px 3px 0 #ff4d6d, 6px 6px 0 rgba(0,0,0,0.3); letter-spacing: 1px; margin-bottom: 8px; }
  h2 { font-size: clamp(16px, 3vw, 26px); color: #ffe066; text-shadow: 2px 2px 0 #b34700; margin-bottom: 14px; }
  p { font-size: clamp(12px, 2vw, 16px); color: #fff; max-width: 560px; line-height: 1.5; margin-bottom: 8px; text-shadow: 1px 1px 2px rgba(0,0,0,0.6); }
  .btn { margin-top: 16px; padding: 12px 32px; font-size: clamp(15px, 2.4vw, 20px); font-weight: bold; color: #fff; background: linear-gradient(180deg, #ff6b9d, #e63946); border: 3px solid #fff; border-radius: 30px; cursor: pointer; box-shadow: 0 6px 0 #8b1e2d, 0 8px 16px rgba(0,0,0,0.4); transition: transform 0.1s; }
  .btn:active { transform: translateY(4px); box-shadow: 0 2px 0 #8b1e2d; }
  .wm { position: absolute; bottom: 10px; left: 0; right: 0; text-align: center; font-size: clamp(9px, 1.4vw, 12px); color: rgba(255,255,255,0.7); letter-spacing: 1px; }
  .wm b { color: #ffe066; }
  #muteBtn { position: absolute; top: 10px; right: 10px; z-index: 20; width: 44px; height: 44px; border-radius: 50%; border: 2px solid #fff; background: rgba(0,0,0,0.4); color: #fff; font-size: 20px; cursor: pointer; }
  #touch { position: absolute; inset: 0; pointer-events: none; z-index: 15; }
  .tbtn { position: absolute; bottom: 20px; width: 68px; height: 68px; border-radius: 50%; border: 3px solid rgba(255,255,255,0.8); background: rgba(255,107,157,0.55); color: #fff; font-size: 26px; font-weight: bold; pointer-events: auto; display: flex; align-items: center; justify-content: center; user-select: none; }
  .tbtn:active { background: rgba(255,107,157,0.9); }
  #tLeft { left: 18px; }
  #tRight { left: 100px; }
  #tJump { right: 18px; background: rgba(80,200,120,0.6); }
  .legend { display: flex; gap: 14px; flex-wrap: wrap; justify-content: center; margin: 10px 0; }
  .legend span { font-size: clamp(11px, 1.8vw, 14px); color: #fff; padding: 4px 10px; border-radius: 12px; border: 2px solid #fff; }
</style>
</head>
<body>
<div id="wrap"><div id="stage">
  <canvas id="cv"></canvas>
  <button id="muteBtn">🔊</button>

  <div id="menu" class="overlay">
    <h1>RANTAI MAKANAN</h1>
    <h2>Panen Produsen</h2>
    <p>Kamu adalah makhluk kecil di ekosistem. Kumpulkan <b>PRODUSEN</b> (tumbuhan) untuk energi & skor, hindari <b>PREDATOR</b>, dan sentuh <b>PENGURAI</b> untuk bonus!</p>
    <div class="legend">
      <span style="background:#2ecc71">🌿 Produsen</span>
      <span style="background:#e74c3c">🦊 Predator</span>
      <span style="background:#9b59b6">🍄 Pengurai</span>
    </div>
    <p style="font-size:clamp(11px,1.7vw,14px);opacity:0.85">Kontrol: ← → / A D untuk bergerak, Spasi / ↑ / W untuk lompat (bisa <b>Double Jump</b>!)</p>
    <button class="btn" id="startBtn">🚀 MULAI</button>
    <div class="wm">Built with <b>AISYS HTML5 Engine</b> · STIKOM YOS SUDARSO</div>
  </div>

  <div id="over" class="overlay hidden">
    <h1>GAME OVER</h1>
    <h2 id="finalScore">Skor: 0</h2>
    <p id="overMsg"></p>
    <button class="btn" id="againBtn">🔄 MAIN LAGI</button>
    <div class="wm">Built with <b>AISYS HTML5 Engine</b> · STIKOM YOS SUDARSO</div>
  </div>

  <div id="touch" class="hidden">
    <div class="tbtn" id="tLeft">◀</div>
    <div class="tbtn" id="tRight">▶</div>
    <div class="tbtn" id="tJump">⤒</div>
  </div>
</div></div>

<script>
(function(){
"use strict";
const cv = document.getElementById('cv');
const ctx = cv.getContext('2d');
let W = 960, H = 540;

function resize(){
  const stage = document.getElementById('stage');
  const r = stage.getBoundingClientRect();
  const ar = 16/9;
  let w = r.width, h = r.height;
  if (w / h > ar) w = h * ar; else h = w / ar;
  cv.style.width = w + 'px'; cv.style.height = h + 'px';
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  cv.width = Math.floor(w * dpr); cv.height = Math.floor(h * dpr);
  W = w; H = h;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
}
window.addEventListener('resize', resize);

// ===== AUDIO =====
let audioCtx = null, muted = false;
function unlockAudio(){
  if (!audioCtx) { try { audioCtx = new (window.AudioContext || window.webkitAudioContext)(); } catch(e){} }
  if (audioCtx && audioCtx.state === 'suspended') audioCtx.resume();
}
function beep(freq, dur, type, vol){
  if (!audioCtx || muted) return;
  const o = audioCtx.createOscillator(), g = audioCtx.createGain();
  o.type = type || 'square'; o.frequency.value = freq;
  g.gain.setValueAtTime(vol || 0.15, audioCtx.currentTime);
  g.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + dur);
  o.connect(g); g.connect(audioCtx.destination);
  o.start(); o.stop(audioCtx.currentTime + dur);
}
const sfx = {
  jump: () => { beep(520, 0.12, 'square', 0.12); setTimeout(()=>beep(700,0.1,'square',0.1), 50); },
  dbl:  () => { beep(700, 0.1, 'sine', 0.12); setTimeout(()=>beep(950,0.1,'sine',0.1), 50); },
  pick: () => { beep(880, 0.08, 'sine', 0.15); setTimeout(()=>beep(1200,0.1,'sine',0.12), 60); },
  hit:  () => { beep(160, 0.25, 'sawtooth', 0.18); },
  bonus:() => { beep(600,0.1,'sine',0.14); setTimeout(()=>beep(800,0.1,'sine',0.14),80); setTimeout(()=>beep(1100,0.15,'sine',0.12),160); },
  over: () => { beep(400,0.2,'sawtooth',0.15); setTimeout(()=>beep(300,0.25,'sawtooth',0.15),180); setTimeout(()=>beep(200,0.4,'sawtooth',0.15),380); }
};
document.getElementById('muteBtn').addEventListener('click', function(e){
  e.stopPropagation(); unlockAudio(); muted = !muted;
  this.textContent = muted ? '🔇' : '🔊';
});

// ===== INPUT =====
const keys = {};
window.addEventListener('keydown', e => {
  if (['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' '].includes(e.key)) e.preventDefault();
  keys[e.key.toLowerCase()] = true;
  if (e.key === ' ' || e.key === 'ArrowUp' || e.key.toLowerCase() === 'w') tryJump();
});
window.addEventListener('keyup', e => { keys[e.key.toLowerCase()] = false; });

const touch = { left: false, right: false };
function bindTouch(id, on, off){
  const el = document.getElementById(id);
  el.addEventListener('touchstart', e => { e.preventDefault(); unlockAudio(); on(); }, {passive:false});
  el.addEventListener('touchend', e => { e.preventDefault(); off(); }, {passive:false});
  el.addEventListener('touchcancel', e => { e.preventDefault(); off(); }, {passive:false});
  el.addEventListener('mousedown', e => { e.preventDefault(); unlockAudio(); on(); });
  el.addEventListener('mouseup', e => { e.preventDefault(); off(); });
  el.addEventListener('mouseleave', () => off());
}
bindTouch('tLeft', () => touch.left = true, () => touch.left = false);
bindTouch('tRight', () => touch.right = true, () => touch.right = false);
bindTouch('tJump', () => tryJump(), () => {});

// ===== GAME STATE =====
const G = {
  state: 'menu', // menu, play, over
  score: 0, lives: 3, energy: 100,
  camX: 0, time: 0,
  player: null, platforms: [], items: [], predators: [], particles: [], floaters: [],
  spawnTimer: 0, worldW: 6000, groundY: 0,
  stars: []
};

const PLAYER_W = 38, PLAYER_H = 46;
const GRAVITY = 2100, MOVE_SPEED = 320, JUMP_V = 780;

function resetGame(){
  G.score = 0; G.lives = 3; G.energy = 100; G.camX = 0; G.time = 0;
  G.particles = []; G.floaters = []; G.items = []; G.predators = [];
  G.spawnTimer = 0;
  G.groundY = H * 0.82;
  G.player = { x: 120, y: G.groundY - PLAYER_H, vx: 0, vy: 0, onGround: false, jumps: 0, face: 1, invuln: 0, anim: 0 };
  // platforms: ground + floating
  G.platforms = [];
  const groundH = H - G.groundY;
  G.platforms.push({ x: -200, y: G.groundY, w: G.worldW + 400, h: groundH + 100, ground: true });
  // floating platforms
  let px = 400;
  const platData = [
    [400, 0.60, 160], [700, 0.48, 140], [1050, 0.62, 180], [1400, 0.50, 150],
    [1750, 0.65, 160], [2100, 0.45, 140], [2450, 0.58, 170], [2850, 0.52, 150],
    [3200, 0.66, 180], [3550, 0.48, 140], [3900, 0.60, 160], [4300, 0.50, 150],
    [4700, 0.64, 170], [5100, 0.46, 140], [5500, 0.58, 160]
  ];
  for (const [x, yf, w] of platData){
    G.platforms.push({ x, y: H * yf, w, h: 22, ground: false });
  }
  // stars background
  G.stars = [];
  for (let i = 0; i < 60; i++){
    G.stars.push({ x: Math.random() * 2000, y: Math.random() * H * 0.6, r: Math.random() * 2 + 1, s: Math.random() * 0.5 + 0.2 });
  }
  // initial items
  for (let i = 0; i < 8; i++) spawnItem(true);
  for (let i = 0; i < 3; i++) spawnPredator(true);
}

// ===== SPAWNING =====
const ITEM_TYPES = [
  { kind: 'produsen', label: '🌿', color: '#2ecc71', pts: 50 },
  { kind: 'produsen', label: '🌱', color: '#27ae60', pts: 50 },
  { kind: 'produsen', label: '🍃', color: '#58d68d', pts: 50 },
  { kind: 'pengurai', label: '🍄', color: '#9b59b6', pts: 100 }
];
const PRED_TYPES = [
  { label: '🦊', color: '#e74c3c' },
  { label: '🐍', color: '#c0392b' },
  { label: '🦅', color: '#d35400' }
];

function spawnItem(initial){
  const t = ITEM_TYPES[Math.floor(Math.random() * ITEM_TYPES.length)];
  const isPengurai = t.kind === 'pengurai';
  // choose platform
  const plats = G.platforms.filter(p => !p.ground);
  let x, y;
  if (Math.random() < 0.55 && plats.length){
    const p = plats[Math.floor(Math.random() * plats.length)];
    x = p.x + 30 + Math.random() * (p.w - 60);
    y = p.y - 34;
  } else {
    x = 300 + Math.random() * (G.worldW - 600);
    y = G.groundY - 34;
  }
  if (initial) x = 350 + Math.random() * (G.worldW - 700);
  G.items.push({ x, y, baseY: y, kind: t.kind, label: t.label, color: t.color, pts: t.pts, bob: Math.random() * Math.PI * 2, alive: true, isPengurai });
}

function spawnPredator(initial){
  const t = PRED_TYPES[Math.floor(Math.random() * PRED_TYPES.length)];
  const x = initial ? 600 + Math.random() * (G.worldW - 900) : G.camX + W + 100 + Math.random() * 300;
  const range = 120 + Math.random() * 100;
  G.predators.push({ x, baseX: x, y: G.groundY - 40, w: 40, h: 40, label: t.label, color: t.color, dir: Math.random() < 0.5 ? 1 : -1, range, speed: 60 + Math.random() * 50, phase: Math.random() * Math.PI * 2 });
}

// ===== PARTICLES =====
function burst(x, y, color, n){
  for (let i = 0; i < n; i++){
    const a = Math.random() * Math.PI * 2, sp = 60 + Math.random() * 180;
    G.particles.push({ x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 60, life: 0.6 + Math.random() * 0.4, max: 1, color, size: 3 + Math.random() * 4 });
  }
}
function floatText(x, y, text, color){
  G.floaters.push({ x, y, text, color, life: 1.1, max: 1.1 });
}

// ===== PHYSICS =====
function tryJump(){
  if (G.state !== 'play') return;
  const p = G.player;
  if (p.onGround){ p.vy = -JUMP_V; p.onGround = false; p.jumps = 1; sfx.jump(); }
  else if (p.jumps < 2){ p.vy = -JUMP_V * 0.9; p.jumps = 2; sfx.dbl(); burst(p.x + PLAYER_W/2, p.y + PLAYER_H, '#ffe066', 8); }
}

function updatePlayer(dt){
  const p = G.player;
  let move = 0;
  if (keys['arrowleft'] || keys['a'] || touch.left) move -= 1;
  if (keys['arrowright'] || keys['d'] || touch.right) move += 1;
  p.vx = move * MOVE_SPEED;
  if (move !== 0) p.face = move;
  p.x += p.vx * dt;
  if (p.x < 0) p.x = 0;
  if (p.x > G.worldW - PLAYER_W) p.x = G.worldW - PLAYER_W;

  p.vy += GRAVITY * dt;
  p.y += p.vy * dt;
  p.onGround = false;

  // platform collision
  for (const pl of G.platforms){
    if (p.x + PLAYER_W > pl.x && p.x < pl.x + pl.w){
      const prevBottom = p.y + PLAYER_H - p.vy * dt;
      if (p.vy >= 0 && prevBottom <= pl.y + 4 && p.y + PLAYER_H >= pl.y && p.y + PLAYER_H <= pl.y + pl.h + 20){
        p.y = pl.y - PLAYER_H; p.vy = 0; p.onGround = true; p.jumps = 0;
      }
    }
  }
  if (p.y > H + 200){ p.y = G.groundY - PLAYER_H; p.vy = 0; }
  if (p.invuln > 0) p.invuln -= dt;
  p.anim += dt * (Math.abs(p.vx) > 10 ? 10 : 3);
}

function updateWorld(dt){
  // camera follows player
  const targetCam = G.player.x - W * 0.35;
  G.camX += (targetCam - G.camX) * Math.min(1, dt * 6);
  if (G.camX < 0) G.camX = 0;
  if (G.camX > G.worldW - W) G.camX = G.worldW - W;

  // items bob
  for (const it of G.items){
    if (!it.alive) continue;
    it.bob += dt * 3;
    it.y = it.baseY + Math.sin(it.bob) * 6;
    // collect
    const p = G.player;
    if (p.x + PLAYER_W > it.x - 14 && p.x < it.x + 14 && p.y + PLAYER_H > it.y - 14 && p.y < it.y + 14){
      it.alive = false;
      if (it.kind === 'produsen'){
        G.score += it.pts; G.energy = Math.min(100, G.energy + 8);
        burst(it.x, it.y, it.color, 12); floatText(it.x, it.y - 10, '+'+it.pts, '#2ecc71'); sfx.pick();
      } else {
        G.score += it.pts; G.energy = Math.min(100, G.energy + 25);
        burst(it.x, it.y, it.color, 18); floatText(it.x, it.y - 10, '+'+it.pts+' BONUS', '#9b59b6'); sfx.bonus();
      }
    }
  }
  G.items = G.items.filter(it => it.alive);

  // predators
  for (const pr of G.predators){
    pr.phase += dt * 2;
    pr.x += pr.dir * pr.speed * dt;
    if (pr.x > pr.baseX + pr.range) { pr.dir = -1; }
    if (pr.x < pr.baseX - pr.range) { pr.dir = 1; }
    // collision with player
    const p = G.player;
    if (p.invuln <= 0 && p.x + PLAYER_W > pr.x && p.x < pr.x + pr.w && p.y + PLAYER_H > pr.y && p.y < pr.y + pr.h){
      G.lives--; p.invuln = 1.5; G.energy = Math.max(0, G.energy - 20);
      burst(p.x + PLAYER_W/2, p.y + PLAYER_H/2, '#e74c3c', 20);
      floatText(p.x, p.y - 10, '-1 NYAWA', '#e74c3c'); sfx.hit();
      // knockback
      p.vy = -400; p.vx = (p.x < pr.x ? -1 : 1) * 300;
      if (G.lives <= 0) gameOver();
    }
  }

  // spawn new items/predators ahead
  G.spawnTimer -= dt;
  if (G.spawnTimer <= 0){
    G.spawnTimer = 1.2 + Math.random() * 0.8;
    if (G.items.length < 14) spawnItem(false);
    if (G.predators.length < 8 && Math.random() < 0.6) spawnPredator(false);
  }
  // cull far-behind entities
  G.items = G.items.filter(it => it.x > G.camX - 200);
  G.predators = G.predators.filter(pr => pr.x > G.camX - 300 && pr.x < G.camX + W + 800);

  // energy drain
  G.energy -= dt * 1.5;
  if (G.energy <= 0){ G.energy = 0; G.lives = 0; gameOver(); }

  // particles
  for (const pt of G.particles){ pt.x += pt.vx * dt; pt.y += pt.vy * dt; pt.vy += 400 * dt; pt.life -= dt; }
  G.particles = G.particles.filter(pt => pt.life > 0);
  for (const f of G.floaters){ f.y -= 40 * dt; f.life -= dt; }
  G.floaters = G.floaters.filter(f => f.life > 0);
}

// ===== RENDERING =====
function roundRect(x, y, w, h, r){
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function drawBackground(){
  // sky gradient
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, '#4facfe');
  g.addColorStop(0.5, '#7bd5f5');
  g.addColorStop(1, '#c2f0c2');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  // sun
  ctx.save();
  ctx.globalAlpha = 0.9;
  const sg = ctx.createRadialGradient(W * 0.82, H * 0.15, 10, W * 0.82, H * 0.15, 90);
  sg.addColorStop(0, '#fff9c4'); sg.addColorStop(1, 'rgba(255,249,196,0)');
  ctx.fillStyle = sg;
  ctx.beginPath(); ctx.arc(W * 0.82, H * 0.15, 90, 0, Math.PI * 2); ctx.fill();
  ctx.restore();

  // parallax hills
  const hillOff = G.camX * 0.3;
  ctx.fillStyle = '#8fd694';
  for (let i = -1; i < 6; i++){
    const bx = (i * 400 - hillOff % 400);
    ctx.beginPath();
    ctx.arc(bx + 200, G.groundY + 40, 220, Math.PI, 0);
    ctx.fill();
  }
  ctx.fillStyle = '#6cc070';
  const hillOff2 = G.camX * 0.5;
  for (let i = -1; i < 8; i++){
    const bx = (i * 300 - hillOff2 % 300);
    ctx.beginPath();
    ctx.arc(bx + 150, G.groundY + 60, 160, Math.PI, 0);
    ctx.fill();
  }

  // stars (cartoon sparkles)
  ctx.save();
  for (const s of G.stars){
    const sx = (s.x - G.camX * 0.15) % (W + 100);
    const px = sx < -50 ? sx + W + 100 : sx;
    ctx.globalAlpha = 0.4 + Math.sin(G.time * s.s + s.x) * 0.3;
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(px, s.y, s.r, 0, Math.PI * 2); ctx.fill();
  }
  ctx.restore();
}

function drawPlatforms(){
  for (const pl of G.platforms){
    const sx = pl.x - G.camX;
    if (sx + pl.w < -50 || sx > W + 50) continue;
    if (pl.ground){
      // grass ground
      const gg = ctx.createLinearGradient(0, pl.y, 0, H);
      gg.addColorStop(0, '#5cb85c'); gg.addColorStop(0.15, '#4a9e4a'); gg.addColorStop(1, '#3d7a3d');
      ctx.fillStyle = gg;
      ctx.fillRect(sx, pl.y, pl.w, pl.h);
      // grass top
      ctx.fillStyle = '#7ed957';
      ctx.fillRect(sx, pl.y, pl.w, 10);
      // grass blades
      ctx.strokeStyle = '#5cb85c'; ctx.lineWidth = 3;
      for (let gx = sx; gx < sx + pl.w; gx += 22){
        ctx.beginPath(); ctx.moveTo(gx, pl.y); ctx.lineTo(gx + 4, pl.y - 10); ctx.stroke();
      }
    } else {
      // floating platform with cartoon style
      ctx.save();
      ctx.shadowColor = 'rgba(0,0,0,0.25)'; ctx.shadowBlur = 8; ctx.shadowOffsetY = 4;
      const pg = ctx.createLinearGradient(0, pl.y, 0, pl.y + pl.h);
      pg.addColorStop(0, '#ffd166'); pg.addColorStop(1, '#f4a261');
      ctx.fillStyle = pg;
      roundRect(sx, pl.y, pl.w, pl.h, 10); ctx.fill();
      ctx.restore();
      ctx.strokeStyle = '#c77d3a'; ctx.lineWidth = 3;
      roundRect(sx, pl.y, pl.w, pl.h, 10); ctx.stroke();
      // grass tuft
      ctx.fillStyle = '#7ed957';
      roundRect(sx + 6, pl.y - 4, pl.w - 12, 8, 4); ctx.fill();
    }
  }
}

function drawPlayer(){
  const p = G.player;
  const sx = p.x - G.camX;
  if (p.invuln > 0 && Math.floor(p.invuln * 12) % 2 === 0) return;
  ctx.save();
  ctx.translate(sx + PLAYER_W/2, p.y + PLAYER_H/2);
  // shadow
  ctx.save(); ctx.globalAlpha = 0.2; ctx.fillStyle = '#000';
  ctx.beginPath(); ctx.ellipse(0, PLAYER_H/2 + 4, PLAYER_W/2, 6, 0, 0, Math.PI*2); ctx.fill(); ctx.restore();
  // body (round blob creature)
  const bob = Math.sin(p.anim) * 2;
  const bg = ctx.createRadialGradient(-6, -8 + bob, 4, 0, bob, PLAYER_W);
  bg.addColorStop(0, '#ffb3c6'); bg.addColorStop(1, '#ff6b9d');
  ctx.fillStyle = bg;
  ctx.beginPath(); ctx.ellipse(0, bob, PLAYER_W/2, PLAYER_H/2, 0, 0, Math.PI*2); ctx.fill();
  ctx.strokeStyle = '#c9184a'; ctx.lineWidth = 3; ctx.stroke();
  // eyes
  ctx.fillStyle = '#fff';
  ctx.beginPath(); ctx.arc(-7 + p.face*2, -6 + bob, 7, 0, Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(7 + p.face*2, -6 + bob, 7, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = '#1a1a2e';
  ctx.beginPath(); ctx.arc(-7 + p.face*4, -6 + bob, 3.5, 0, Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.arc(7 + p.face*4, -6 + bob, 3.5, 0, Math.PI*2); ctx.fill();
  // mouth
  ctx.strokeStyle = '#c9184a'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(p.face*2, 6 + bob, 5, 0.1, Math.PI - 0.1); ctx.stroke();
  // feet
  ctx.fillStyle = '#c9184a';
  const footOff = Math.sin(p.anim) * 4;
  ctx.beginPath(); ctx.ellipse(-9, PLAYER_H/2 - 2 + bob, 6, 4, 0, 0, Math.PI*2); ctx.fill();
  ctx.beginPath(); ctx.ellipse(9, PLAYER_H/2 - 2 - bob, 6, 4, 0, 0, Math.PI*2); ctx.fill();
  ctx.restore();
}

function drawEntities(){
  // items
  for (const it of G.items){
    const sx = it.x - G.camX;
    if (sx < -60 || sx > W + 60) continue;
    ctx.save();
    ctx.translate(sx, it.y);
    // glow
    ctx.shadowColor = it.color; ctx.shadowBlur = 14;
    ctx.fillStyle = 'rgba(255,255,255,0.85)';
    ctx.beginPath(); ctx.arc(0, 0, 16, 0, Math.PI*2); ctx.fill();
    ctx.shadowBlur = 0;
    ctx.strokeStyle = it.color; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.arc(0, 0, 16, 0, Math.PI*2); ctx.stroke();
    ctx.font = '20px serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(it.label, 0, 1);
    ctx.restore();
  }
  // predators
  for (const pr of G.predators){
    const sx = pr.x - G.camX;
    if (sx < -80 || sx > W + 80) continue;
    ctx.save();
    ctx.translate(sx + pr.w/2, pr.y + pr.h/2 + Math.sin(pr.phase) * 3);
    // angry aura
    ctx.shadowColor = '#e74c3c'; ctx.shadowBlur = 12;
    ctx.fillStyle = pr.color;
    ctx.beginPath(); ctx.ellipse(0, 0, pr.w/2, pr.h/2, 0, 0, Math.PI*2); ctx.fill();
    ctx.shadowBlur = 0;
    ctx.strokeStyle = '#7b1e1e'; ctx.lineWidth = 3; ctx.stroke();
    // eyes (angry)
    ctx.fillStyle = '#fff';
    ctx.beginPath(); ctx.arc(-8, -6, 6, 0, Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.arc(8, -6, 6, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = '#000';
    ctx.beginPath(); ctx.arc(-8, -6, 3, 0, Math.PI*2); ctx.fill();
    ctx.beginPath(); ctx.arc(8, -6, 3, 0, Math.PI*2); ctx.fill();
    // angry brows
    ctx.strokeStyle = '#000'; ctx.lineWidth = 2.5;
    ctx.beginPath(); ctx.moveTo(-13, -13); ctx.lineTo(-4, -9); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(13, -13); ctx.lineTo(4, -9); ctx.stroke();
    // emoji label
    ctx.font = '22px serif'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(pr.label, 0, 12);
    ctx.restore();
  }
}

function drawParticles(){
  for (const pt of G.particles){
    const sx = pt.x - G.camX;
    ctx.globalAlpha = Math.max(0, pt.life / pt.max);
    ctx.fillStyle = pt.color;
    // star shape
    ctx.save(); ctx.translate(sx, pt.y); ctx.rotate(pt.life * 5);
    ctx.beginPath();
    for (let i = 0; i < 5; i++){
      const a = i * Math.PI * 2 / 5 - Math.PI/2;
      const a2 = a + Math.PI / 5;
      ctx.lineTo(Math.cos(a) * pt.size, Math.sin(a) * pt.size);
      ctx.lineTo(Math.cos(a2) * pt.size * 0.5, Math.sin(a2) * pt.size * 0.5);
    }
    ctx.closePath(); ctx.fill();
    ctx.restore();
  }
  ctx.globalAlpha = 1;
  for (const f of G.floaters){
    const sx = f.x - G.camX;
    ctx.globalAlpha = Math.max(0, f.life / f.max);
    ctx.font = 'bold 18px Trebuchet MS';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#000'; ctx.fillText(f.text, sx + 2, f.y + 2);
    ctx.fillStyle = f.color; ctx.fillText(f.text, sx, f.y);
  }
  ctx.globalAlpha = 1;
}

function drawHUD(){
  // score panel
  ctx.save();
  ctx.fillStyle = 'rgba(0,0,0,0.35)';
  roundRect(12, 12, 200, 78, 14); ctx.fill();
  ctx.fillStyle = '#fff'; ctx.font = 'bold 20px Trebuchet MS'; ctx.textAlign = 'left'; ctx.textBaseline = 'top';
  ctx.fillText('SKOR: ' + G.score, 24, 20);
  // lives
  ctx.font = '18px serif';
  let lx = 24;
  for (let i = 0; i < 3; i++){
    ctx.globalAlpha = i < G.lives ? 1 : 0.25;
    ctx.fillText('❤️', lx, 48); lx += 24;
  }
  ctx.globalAlpha = 1;
  // energy bar
  ctx.fillStyle = 'rgba(255,255,255,0.3)';
  roundRect(24, 74, 176, 10, 5); ctx.fill();
  const eg = ctx.createLinearGradient(24, 0, 200, 0);
  eg.addColorStop(0, '#2ecc71'); eg.addColorStop(1, '#a8e063');
  ctx.fillStyle = eg;
  roundRect(24, 74, 176 * (G.energy / 100), 10, 5); ctx.fill();
  ctx.restore();

  // watermark in-game
  ctx.save();
  ctx.globalAlpha = 0.35;
  ctx.fillStyle = '#ffffff';
  ctx.font = 'bold 12px Trebuchet MS';
  ctx.textAlign = 'right'; ctx.textBaseline = 'bottom';
  ctx.fillText('AISYS HTML5 Engine', W - 14, H - 10);
  ctx.restore();
}

function render(){
  drawBackground();
  drawPlatforms();
  drawEntities();
  drawPlayer();
  drawParticles();
  drawHUD();
}

// ===== LOOP =====
let last = 0;
function loop(ts){
  if (!last) last = ts;
  let dt = (ts - last) / 1000; last = ts;
  if (dt > 0.05) dt = 0.05;
  if (G.state === 'play'){
    G.time += dt;
    updatePlayer(dt);
    updateWorld(dt);
  }
  render();
  requestAnimationFrame(loop);
}

// ===== FLOW =====
function startGame(){
  unlockAudio();
  resetGame();
  G.state = 'play';
  document.getElementById('menu').classList.add('hidden');
  document.getElementById('over').classList.add('hidden');
  document.getElementById('touch').classList.remove('hidden');
}
function gameOver(){
  if (G.state === 'over') return;
  G.state = 'over';
  sfx.over();
  document.getElementById('finalScore').textContent = 'Skor: ' + G.score;
  let msg = 'Energi habis! Ingat, energi rantai makanan berasal dari produsen.';
  if (G.lives <= 0) msg = 'Nyawa habis! Hati-hati predator — mereka konsumen, bukan produsen.';
  document.getElementById('overMsg').textContent = msg;
  document.getElementById('over').classList.remove('hidden');
  document.getElementById('touch').classList.add('hidden');
}

document.getElementById('startBtn').addEventListener('click', startGame);
document.getElementById('againBtn').addEventListener('click', startGame);
document.getElementById('menu').addEventListener('click', unlockAudio);
document.getElementById('over').addEventListener('click', unlockAudio);

resize();
resetGame();
requestAnimationFrame(loop);
})();
</script>
